"""Journal record builder for tests."""
import zlib

def rec(seq, kind, txid, payload=b"", crc=None, plen=None):
    n = len(payload) if plen is None else plen
    body = (n.to_bytes(4, "little") + seq.to_bytes(4, "little")
            + bytes([kind]) + txid.to_bytes(4, "little") + payload)
    c = zlib.crc32(body) if crc is None else crc
    return body + c.to_bytes(4, "little")

def begin(seq, txid, **kw):
    return rec(seq, 1, txid, b"", **kw)

def patch(seq, txid, page, off, data, **kw):
    p = (page.to_bytes(2, "little") + off.to_bytes(2, "little")
         + len(data).to_bytes(2, "little") + data)
    return rec(seq, 2, txid, p, **kw)

def commit(seq, txid, count, digest, **kw):
    return rec(seq, 3, txid, count.to_bytes(4, "little") + digest.to_bytes(4, "little"), **kw)

def abort(seq, txid, **kw):
    return rec(seq, 4, txid, b"", **kw)

def seal(payloads):
    """Correct seal for a list of PATCH payloads."""
    return zlib.crc32(b"".join(payloads))
